mapper.select:
SELECT

FROM app_movie m


ORDER BY ${params.sortColumn} ${params.orderKeyword}
LIMIT #{params.offset}, #{params.limit}

SELECT

FROM app_movie m

WHERE m.id != #{id}

    AND (
        m.movie_type_id = #{typeId}
        OR EXISTS (
            SELECT 1
            FROM app_movie_type_rel rel
            WHERE rel.movie_id = m.id
              AND rel.type_id = #{typeId}
        )
    )

ORDER BY m.click_count DESC, m.total_score DESC, m.id DESC
LIMIT #{limit}

SELECT
FROM app_movie m
ORDER BY m.click_count DESC, m.id DESC LIMIT #{limit}

SELECT
FROM app_movie m
ORDER BY m.like_count DESC, m.id DESC LIMIT #{limit}

SELECT
FROM app_movie m
ORDER BY m.favorite_count DESC, m.id DESC LIMIT #{limit}
